package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.*;
import com.openggf.game.soniccd.media.*;
import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.nio.ReadOnlyBufferException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Actual-media immutable R11B DATA requirements. No Frame, World, entry or loading permit. */
class TestCdOriginalR11bSharedPlayerTerrainData {
 private static final CdPpzDataLayout.Programme B=CdPpzDataLayout.Programme.R11B;
 private static final int[] OFFSETS={0x579E,0x574E,0x4514,0x82E,0xB14};
 private static final int[] LENGTHS={578,60,6,640,257};
 private static final String[] HASHES={"96c145e86b5f841f36dbfca9361c7139df4ff5705423566836d361ace6098af9","adcb220955503a487e05e9d1310f244e7c84e50c26c0fbf5c2a64e968f2f4c1a","203fe6a5ab55693db5a4daca78171984996c54a85119395dbd59d5fae00c7218","bbde7b84eb90b56a2425842a67a0ff0316b3f3b0ff49b956f9b86c1267d75bb9","a981a16e050ef47017e44f23c991256a478755f1b415667f56e6788d1b655295"};
 private record Fixture(CdDiscHeader header,CdObservedMediaIdentity identity,CdProgramCatalogue catalogue,CdMmdImage b,CdMmdImage a){}
 private static Fixture retained;
 private static synchronized Fixture actual()throws Exception{
  if(retained==null)try(var media=TestCdCczProgrammeData.open()){retained=new Fixture(media.header(),media.identity(),media.catalogue().orElseThrow(),media.mmd(CdNativeFile.R11B),media.mmd(CdNativeFile.R11A));}return retained;
 }
 private static CdProgramAssets source(Fixture f,CdMmdImage image){var actual=mock(CdProgramAssets.class);when(actual.header()).thenReturn(f.header());when(actual.identity()).thenReturn(f.identity());when(actual.catalogue()).thenReturn(Optional.of(f.catalogue()));try{when(actual.mmd(CdNativeFile.R11B)).thenReturn(image);}catch(IOException failure){throw new AssertionError(failure);}return actual;}
 private static CdProgrammeReader reader(CdMmdImage image)throws Exception{return CdProgrammeReader.open(source(actual(),image),B.payload().stage());}
 private static CdR11aPlayerAssets legacy(CdMmdImage image,CdSonicVisualAssets sonic){return CdR11aPlayerAssets.decode(image.readFile(OFFSETS[0],LENGTHS[0]),image.readFile(OFFSETS[1],LENGTHS[1]),image.readFile(OFFSETS[2],LENGTHS[2]),image.readFile(0x29D8,4),image.readFile(OFFSETS[3],LENGTHS[3]),image.readFile(OFFSETS[4],LENGTHS[4]),sonic);}
 private static void sameValues(CdR11aPlayerAssets a,CdR11aPlayerAssets b){assertSame(a.sonic(),b.sonic());assertArrayEquals(a.animationTable().copy(),b.animationTable().copy());assertArrayEquals(a.miniAnimations().copy(),b.miniAnimations().copy());assertArrayEquals(a.rampChunks().copy(),b.rampChunks().copy());assertArrayEquals(a.specialChunks().copy(),b.specialChunks().copy());assertArrayEquals(a.sineTable().copy(),b.sineTable().copy());assertArrayEquals(a.arcTanTable().copy(),b.arcTanTable().copy());for(int i=0;i<60;i++){assertEquals(a.animation(i).relativeOffset(),b.animation(i).relativeOffset());assertArrayEquals(a.animation(i).bytes().copy(),b.animation(i).bytes().copy());}}
 @Test void originalPastBindingIsPpz198OrdinaryZeroAndNativeZoneActZero(){var d=CdProgrammeDefinition.select(B.payload().stage());var p=d.player().orElseThrow();assertTrue(d.dataOnly());assertTrue(d.r3().isEmpty());assertTrue(d.tt().isEmpty());assertEquals(CdR11aPlayerAssets.SourceGraph.PPZ,p.graph());assertEquals(0,p.ordinaryPeriod());assertEquals(0,p.ordinaryZoneActWord());assertEquals(198,p.frames());assertSame(d.visual(),p.visual());assertEquals(CdSonicVisualAssets.SourceFormat.FRAMES_198_WITH_EVEN_BYTE,p.visual().format());assertEquals(78,d.raw().size());assertEquals(37,d.sources().size());}
 @Test void fiveLazyRolesUseTheirOwnOriginalPastOperandsAndHashes()throws Exception{var r=reader(actual().b());var keys=CdPpzProgrammeProfiles.R11PastPlayerView.values();assertEquals(5,keys.length);for(int i=0;i<keys.length;i++){var key=keys[i];assertEquals(OFFSETS[i],key.offset());assertEquals(LENGTHS[i],key.length());assertEquals(HASHES[i],key.sha256());var value=r.playerRole(key.role());assertSame(value,r.view(key));assertSame(value,r.playerRole(key.role()));assertArrayEquals(actual().b().readFile(OFFSETS[i],LENGTHS[i]),value.copy());assertEquals(HASHES[i],CdR11aProfile.sha256(value.copy()));}}
 @Test void source198RetainsTheActualEvenWithoutRelabelling167Or188()throws Exception{var r=reader(actual().b());assertEquals(198,r.sonic().mappingFrames().size());assertEquals(CdSonicVisualAssets.SourceFormat.FRAMES_198_WITH_EVEN_BYTE,r.sonic().sourceFormat());assertEquals(0,actual().b().readFile(0x30F5F,1)[0]);assertEquals(69472,r.view(B.range("PlayerArtRead")).length());assertEquals("94edeaff466c9e0c8ddd0b090a99b24bca663b8c40ac1dcd45c530de60e9ce64",CdR11aProfile.sha256(r.view(B.range("PlayerArtRead")).copy()));assertEquals(60,r.ppzPlayerAssets().animations().size());}
 @Test void allPlayerPathsShareOneReaderCacheAndVisual()throws Exception{var r=reader(actual().b());var p=r.ppzPlayerAssets();assertSame(p,r.ppzPlayerAssets());assertSame(p,CdR11aPlayerAssets.fromProgramme(r));assertSame(r.sonic(),p.sonic());assertEquals(CdR11aPlayerAssets.SourceGraph.PPZ,p.sourceGraph());assertTrue(p.ownsProgramme(r));sameValues(legacy(actual().b(),r.sonic()),p);}
 @Test void dataAndPlayerFacadesBorrowExactlyTheSameTerrainAndReader()throws Exception{var r=reader(actual().b());var data=CdPpzProgrammeData.fromReader(r);var stage=data.playerSource();assertSame(stage,r.playerSource());assertSame(r.ppzPlayerAssets(),stage.player());assertSame(r.sonic(),stage.sonic());assertSame(r.terrain(),stage.terrain());assertSame(data.terrain(),stage.terrain());assertTrue(data.ownsReader(r));assertTrue(stage.ownsProgrammeReader(r));assertEquals(0,stage.nativeZoneActWord());assertEquals(0,stage.ordinaryPeriod());assertEquals(0x230F60,stage.mappingAddress());}
 @Test void equalIndependentReadersNeverShareCachedPlayerOrTerrainProvenance()throws Exception{var f=actual();var media=source(f,f.b());var one=CdProgrammeReader.open(media,B.payload().stage());var two=CdProgrammeReader.open(media,B.payload().stage());var p=one.ppzPlayerAssets();assertNotSame(p,two.ppzPlayerAssets());assertNotSame(one.sonic(),two.sonic());assertNotSame(one.terrain(),two.terrain());assertTrue(p.ownsProgramme(one));assertFalse(p.ownsProgramme(two));assertFalse(p.ownsProgramme(null));assertThrows(IllegalArgumentException.class,()->one.requirePlayerTerrain(two.terrain()));verify(media,times(2)).mmd(CdNativeFile.R11B);}
 @Test void canonicalPastRoleKeysRejectPresentAndEqualForeignDeclarations()throws Exception{var r=reader(actual().b());assertThrows(IllegalArgumentException.class,()->r.view(CdPpzProgrammeProfiles.R11PlayerView.ANI));var key=B.range("SpecChunks");assertThrows(IllegalArgumentException.class,()->r.view(new CdPpzDataLayout.Range(key.key(),key.fileOffset(),key.length(),key.sha256())));assertThrows(IllegalArgumentException.class,()->r.view(CdPpzDataLayout.Programme.R11A.range("SpecChunks")));}
 @Test void roleReadsRemainLazyAndUseExistingPpzArgumentOrder()throws Exception{var image=spy(actual().b());var r=reader(image);clearInvocations(image);for(int i=0;i<5;i++)verify(image,never()).readFile(OFFSETS[i],LENGTHS[i]);var p=r.ppzPlayerAssets();var ordered=inOrder(image);for(int i=0;i<5;i++)ordered.verify(image).readFile(OFFSETS[i],LENGTHS[i]);assertSame(p,r.ppzPlayerAssets());for(int i=0;i<5;i++)verify(image,times(1)).readFile(OFFSETS[i],LENGTHS[i]);}
 @Test void failedLazyRolePublishesNoPlayerAndRetainsOnlyEarlierReadViews()throws Exception{var image=spy(actual().b());var r=reader(image);clearInvocations(image);var fault=new IndexOutOfBoundsException("unavailable actual MINI");doThrow(fault).when(image).readFile(OFFSETS[1],LENGTHS[1]);assertSame(fault,assertThrows(IndexOutOfBoundsException.class,r::ppzPlayerAssets));verify(image,never()).readFile(OFFSETS[2],LENGTHS[2]);doCallRealMethod().when(image).readFile(OFFSETS[1],LENGTHS[1]);var p=r.ppzPlayerAssets();assertSame(p,r.ppzPlayerAssets());verify(image,times(1)).readFile(OFFSETS[0],LENGTHS[0]);verify(image,times(2)).readFile(OFFSETS[1],LENGTHS[1]);}
 @Test void changedRoleBytesFailTheirOwnHashBeforeAnyPlayerCache()throws Exception{var image=spy(actual().b());var r=reader(image);var bad=actual().b().readFile(OFFSETS[0],LENGTHS[0]);bad[0]^=1;doReturn(bad).when(image).readFile(OFFSETS[0],LENGTHS[0]);assertThrows(IllegalArgumentException.class,r::ppzPlayerAssets);doCallRealMethod().when(image).readFile(OFFSETS[0],LENGTHS[0]);sameValues(legacy(actual().b(),r.sonic()),r.ppzPlayerAssets());}
 @Test void cacheHitRevalidatesTheActualRetainedOriginalImage()throws Exception{var image=spy(actual().b());var r=reader(image);var p=r.ppzPlayerAssets();int bytes=image.fileBytes();var bad=actual().b().readFile(0,bytes);bad[127]^=1;doReturn(bad).when(image).readFile(0,bytes);assertThrows(IllegalStateException.class,r::ppzPlayerAssets);doCallRealMethod().when(image).readFile(0,bytes);assertSame(p,r.ppzPlayerAssets());}
 @Test void sharedHeaderAndForeignPresentImageCannotClaimPastData()throws Exception{var f=actual();assertThrows(IOException.class,()->CdProgrammeReader.open(source(f,f.a()),B.payload().stage()));}
 @Test void r11aOnlyLoadingAggregateAndPlanBridgesRemainClosedToPast()throws Exception{var r=reader(actual().b());var data=CdPpzProgrammeData.fromReader(r);assertThrows(IllegalArgumentException.class,r::retainedOriginalR11Image);assertThrows(IllegalArgumentException.class,r::originalR11PlayerAssets);assertThrows(IllegalArgumentException.class,r::originalR11LoadPlan);assertSame(r.levelLoadingSource(),data.levelLoadingSource());assertEquals(CdLevelLoadingSource.Completion.STANDARD,data.levelLoadingSource().completion());assertThrows(IllegalArgumentException.class,r::originalR11TerrainProducts);assertFalse(data.playerSource().ownsPresent(null));assertFalse(data.playerSource().ownsPast(null));}
 @Test void theOtherEightPpzPlayerBindingsStillRejectWithoutInventedRoles()throws Exception{try(var media=TestCdCczProgrammeData.open()){for(var p:CdPpzDataLayout.Programme.values())if(p!=B&&p!=CdPpzDataLayout.Programme.R11A){var r=CdProgrammeReader.open(media,p.payload().stage());assertTrue(r.definition().player().isEmpty());assertThrows(UnsupportedOperationException.class,r::playerBinding);}}}
 @Test void presentCacheAndItsLegacyBridgeKeepExactIdentityAndInputs()throws Exception{try(var media=TestCdCczProgrammeData.open()){var r=CdProgrammeReader.open(media,CdStagePayload.R11A.stage());var p=r.originalR11PlayerAssets();assertSame(p,r.ppzPlayerAssets());assertSame(p,CdR11aPlayerAssets.fromProgramme(r));assertSame(p,r.playerSource().player());assertEquals(1,r.playerSource().ordinaryPeriod());assertEquals(0x599A,r.definition().borrowed().get(CdPpzProgrammeProfiles.R11PlayerView.ANI).offset());assertSame(r.playerRole(CdProgrammeReader.Role.ANI),r.view(CdPpzProgrammeProfiles.R11PlayerView.ANI));assertThrows(IllegalArgumentException.class,()->r.fileOffset(CdPpzProgrammeProfiles.R11PlayerView.ANI));assertEquals(CdLevelLoadingSource.Completion.STANDARD,r.levelLoadingSource().completion());}}
 @Test void tt188WaterProfileAndPlayerCacheStayUnchanged()throws Exception{try(var media=TestCdCczProgrammeData.open()){var r=CdProgrammeReader.open(media,CdStagePayload.R41A.stage());var stage=r.playerSource();assertEquals(CdR11aPlayerAssets.SourceGraph.R4,stage.player().sourceGraph());assertEquals(188,stage.sonic().mappingFrames().size());assertEquals(CdLevelLoadingSource.Completion.WATER_PALETTE_AFTER_FADE,r.levelLoadingSource().completion());assertThrows(IllegalArgumentException.class,r::ppzPlayerAssets);assertSame(stage,r.playerSource());}}
 @Test void legacyPurePastDecoderKeepsValuesWithoutClaimingReaderOwnership()throws Exception{var r=reader(actual().b());var legacy=legacy(actual().b(),r.sonic());sameValues(legacy,r.ppzPlayerAssets());assertFalse(legacy.ownsProgramme(r));assertEquals(CdR11aPlayerAssets.SourceGraph.PPZ,legacy.sourceGraph());}
 @Test void terrainUsesTheAlreadyDeclaredSharedProductsAndReadRoles()throws Exception{var r=reader(actual().b());var terrain=r.terrain();assertSame(terrain,r.terrain());assertArrayEquals(r.decoded(B.range("LevelBlocks")).bytes().copy(),terrain.blocks().copy());assertArrayEquals(r.decoded(B.range("Art_LevelTiles")).bytes().copy(),terrain.patterns().copy());assertArrayEquals(r.playerRole(CdProgrammeReader.Role.CHUNKS).copy(),terrain.chunks().copy());assertEquals(5280,terrain.blocks().length());assertEquals(23872,terrain.patterns().length());assertEquals(54272,terrain.chunks().length());assertEquals(42,terrain.layout().columns(CdStageTerrain.Plane.FOREGROUND));assertEquals(4,terrain.layout().rows(CdStageTerrain.Plane.FOREGROUND));}
 @Test void unavailableStagingAndPatternComplementsAreNeverKnownZero()throws Exception{var t=reader(actual().b()).terrain();assertEquals(CdStageTerrain.ReferencePolicy.SELECTED_KNOWN_SOURCE,t.profile().referencePolicy());var block=assertThrows(CdStageTerrain.UnavailableRead.class,()->t.blockWord(t.blockCount(),0,0));assertEquals(CdStageTerrain.ReadOwner.BLOCK_STAGING,block.owner());var pixel=assertThrows(CdStageTerrain.UnavailableRead.class,()->t.pixel(t.patternCount(),0,0));assertEquals(CdStageTerrain.ReadOwner.PATTERN_SOURCE,pixel.owner());assertThrows(CdStageTerrain.UnavailableRead.class,()->t.chunkWord(t.chunkCount()+1,0,0));assertThrows(CdStageTerrain.UnavailableRead.class,()->t.collision().idForBlock(800));assertThrows(UnsupportedOperationException.class,t::shape);}
 @Test void commonLoadParserAndEntryDataRemainTheSameReaderProducts()throws Exception{var r=reader(actual().b());var data=CdPpzProgrammeData.fromReader(r);assertSame(r.loadTables(),r.loadTables());assertSame(r.loadTables(),data.tables());assertSame(r.view(B.range("SpecChunks")),data.entryData().specialChunks());assertSame(r.view(B.range("CamBounds")),data.entryData().cameraBounds());}
 @Test void returnedPlayerAndRoleBytesRemainImmutable()throws Exception{var r=reader(actual().b());var p=r.ppzPlayerAssets();var old=p.animationTable().copy();var copied=p.animationTable().copy();Arrays.fill(copied,(byte)0);assertArrayEquals(old,p.animationTable().copy());assertThrows(ReadOnlyBufferException.class,()->r.playerRole(CdProgrammeReader.Role.MINI).buffer().put((byte)0));assertThrows(UnsupportedOperationException.class,()->p.animations().clear());assertSame(p,r.ppzPlayerAssets());}
}
